        ("p99.9", hist.value_at_quantile(0.999) as f64, 0.999),
        ("p99.99", hist.value_at_quantile(0.9999) as f64, 0.9999),
        ("max", hist.max() as f64, 1.0),
    ];

    // Build rows with band counts (samples between adjacent percentiles).
    let mut rows: Vec<Row> = Vec::new();
    let mut prev_pct = 0.0;
    for (label, raw, pct) in &percentiles {
        let band = ((pct - prev_pct) * sample_count).round() as u64;
        rows.push(Row::with_band(*label, *raw, adj, band));
