        .max()
        .unwrap_or(0);
    let adj_w = rendered
        .iter()
        .filter_map(|(_, _, a, _)| a.as_ref().map(String::len))
        .max()
        .unwrap_or(0);
    let band_w = rendered
        .iter()
        .filter_map(|(_, _, _, b)| b.as_ref().map(String::len))
        .max()
        .unwrap_or(0);

    // Fixed layout pieces: 2-space indent, 8-wide label, 4-space gap
    // between columns.
    const INDENT: &str = "  ";
    const LABEL_W: usize = 8;
    const GAP: &str = "    ";

    // Header row: right-align each label over its numeric column.
    let raw_col_end = INDENT.len() + LABEL_W + 1 + raw_w;
    let adj_col_gap = " ns".len() + GAP.len() + adj_w;
    let band_col_gap = " ns".len() + GAP.len() + band_w;
    println!(
        "{:>raw_col_end$}{:>adj_col_gap$}{:>band_col_gap$}",
        "raw", "adjusted", "band",
    );

    // Data rows: label left-aligned, numbers right-aligned in their
    // data-driven widths.
    for (label, raw_s, adj_s, band_s) in &rendered {
        match (adj_s, band_s) {
