// Build rows with band counts. Each row's band = samples from this
// percentile to the next (current→next). max has no band since it's
// the extreme value within p99's band, not its own band.
let mut rows: Vec<Row> = Vec::new();
for (i, (label, raw, pct)) in percentiles.iter().enumerate() {
    let next_pct = percentiles.get(i + 1).map(|(_, _, p)| *p);
    match next_pct {
        Some(np) => {
            let band = ((np - pct) * sample_count).round() as u64;
            rows.push(Row::with_band(label, *raw, adj, band));
        }
        None => rows.push(Row::with_adj(label, *raw, adj)),
    }
}

