    let sample_count = hist.len() as f64;
    let percentiles: Vec<(&str, f64, f64)> = vec![
        ("min", hist.min() as f64, 1.0 / sample_count),
        ("p1", hist.value_at_quantile(0.01) as f64, 0.01),
        ("p10", hist.value_at_quantile(0.10) as f64, 0.10),
