        ("p99", hist.value_at_quantile(0.99) as f64, 0.99),
        //("p99.9", hist.value_at_quantile(0.999) as f64, 0.999),
        //("p99.99", hist.value_at_quantile(0.9999) as f64, 0.9999),
        ("max", hist.max() as f64, 1.0),
    ];

    // Build rows with band counts. Each row's band = samples from this
