    let step_cost_ns = estimate_step_cost(bench);
    let framing_ns = cfg.overhead.framing_per_sample_ns.max(1.0);
    let inner = cfg
        .inner_override
        .unwrap_or_else(|| pick_inner(step_cost_ns, framing_ns));
    let iterations = cfg
        .iterations_override
        .unwrap_or_else(|| pick_iterations(step_cost_ns, inner, cfg.target_seconds));

    let (hist, duration_s) = run_bench(bench, iterations, inner);
    (hist, iterations, inner, duration_s)
}

fn estimate_step_cost<B: Bench>(bench: &mut B) -> f64 {
    let mut samples: Vec<f64> = (0..ESTIMATE_SAMPLES)
        .map(|_| {
            let start = minstant::Instant::now();
            for _ in 0..ESTIMATE_STEPS {
                black_box(bench.step());
            }
            let total = start.elapsed().as_nanos() as u64;
            total as f64 / ESTIMATE_STEPS as f64
        })
        .collect();
    samples.sort_by(|a, b| a.partial_cmp(b).unwrap());
    samples[ESTIMATE_SAMPLES / 2]
}

fn pick_inner(step_cost_ns: f64, framing_ns: f64) -> u64 {
    let target = (FRAMING_DOMINATION_RATIO * framing_ns / step_cost_ns).ceil() as u64;
    target.clamp(1, MAX_INNER)
}

fn pick_iterations(step_cost_ns: f64, inner: u64, target_seconds: f64) -> u64 {
    let target_ns = target_seconds * 1e9;
    let per_sample_ns = inner as f64 * step_cost_ns;
    let raw = (target_ns / per_sample_ns).ceil() as u64;
    raw.clamp(MIN_ITERATIONS, MAX_ITERATIONS)
}

fn run_bench<B: Bench>(bench: &mut B, iterations: u64, inner: u64) -> (Histogram<u64>, f64) {
    // 1 ns to 60 s, 3 sig figs
    let mut hist = Histogram::<u64>::new_with_bounds(1, 60_000_000_000, 3).unwrap();

    let run_start = minstant::Instant::now();
    for _ in 0..iterations {
        let start = minstant::Instant::now();
        for _ in 0..inner {
            black_box(bench.step());
        }
        let elapsed_ns = start.elapsed().as_nanos() as u64;
        hist.record(round_elapsed(elapsed_ns, inner)).unwrap();
    }
    let duration_s = run_start.elapsed().as_nanos() as f64 / 1e9;

    (hist, duration_s)
}

fn round_elapsed(elapsed_ns: u64, inner: u64) -> u64 {
    (elapsed_ns + inner / 2) / inner
}

pub fn fmt_commas(n: u64) -> String {
    let s = n.to_string();
    let mut result = String::new();
    for (i, c) in s.chars().rev().enumerate() {
        if i > 0 && i % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    result.chars().rev().collect()
}

pub fn fmt_commas_f64(n: f64, decimals: usize) -> String {
    let s = format!("{n:.decimals$}");
    let (sign, body) = match s.strip_prefix('-') {
        Some(rest) => ("-", rest),
        None => ("", s.as_str()),
    };
    let (int_part, frac_part) = match body.find('.') {
        Some(i) => (&body[..i], &body[i..]),
        None => (body, ""),
    };
    let int_num: u64 = int_part.parse().unwrap_or(0);
    format!("{sign}{}{frac_part}", fmt_commas(int_num))
}

pub fn print_histogram(
    name: &str,
    iterations: u64,
    inner: u64,
    duration_s: f64,
    hist: &Histogram<u64>,
    overhead: &Overhead,
) {
    // Header line: bench name + logfmt-style metadata. `adj` is the
    // apparatus overhead subtracted from each sample downstream.
    let adj = overhead.per_call_ns(inner);
    let total = iterations * inner;
    println!(
        "{name} [duration={:.1}s outer={} inner={} calls={} adj/call={}ns]:",
        duration_s,
        fmt_commas(iterations),
        inner,
        fmt_commas(total),
        fmt_commas_f64(adj, 2),
    );

    // Percentile definitions: (label, value, cumulative fraction).
    // min uses 1/total so its band count = 1; max uses 1.0.
    let sample_count = hist.len() as f64;
    let percentiles: Vec<(&str, f64, f64)> = vec![
        ("min", hist.min() as f64, 1.0 / sample_count),
        ("p1", hist.value_at_quantile(0.01) as f64, 0.01),
        ("p10", hist.value_at_quantile(0.10) as f64, 0.10),
        ("p20", hist.value_at_quantile(0.20) as f64, 0.20),
        ("p30", hist.value_at_quantile(0.30) as f64, 0.30),
        ("p40", hist.value_at_quantile(0.40) as f64, 0.40),
        ("p50", hist.value_at_quantile(0.50) as f64, 0.50),
        ("p60", hist.value_at_quantile(0.60) as f64, 0.60),
        ("p70", hist.value_at_quantile(0.70) as f64, 0.70),
        ("p80", hist.value_at_quantile(0.80) as f64, 0.80),
        ("p90", hist.value_at_quantile(0.90) as f64, 0.90),
        ("p99", hist.value_at_quantile(0.99) as f64, 0.99),
        //("p99.9", hist.value_at_quantile(0.999) as f64, 0.999),
        //("p99.99", hist.value_at_quantile(0.9999) as f64, 0.9999),
        ("max", hist.max() as f64, 1.0),
    ];

    // Build rows with band counts. Each percentile row's band = samples
    // from this percentile to the next (current→next). min and max are
    // extremes: their bands show the count in the outermost 0.01% tail.
    let tail_band = (0.0001 * sample_count).round().max(1.0) as u64;
    let mut rows: Vec<Row> = Vec::new();
    for (i, (label, raw, pct)) in percentiles.iter().enumerate() {
        if *label == "min" || *label == "max" {
            rows.push(Row::with_band(label, *raw, adj, tail_band));
        } else if let Some((_, _, np)) = percentiles.get(i + 1) {
            let band = ((np - pct) * sample_count).round() as u64;
            rows.push(Row::with_band(label, *raw, adj, band));
        } else {
            rows.push(Row::with_adj(label, *raw, adj));
        }
    }
    rows.push(Row::with_adj("mean", hist.mean(), adj));
    rows.push(Row::raw_only("stdev", hist.stdev()));

    // Render each row to its final strings so we can size columns from
    // the actual widths.
    let rendered: Vec<(&str, String, Option<String>, Option<String>)> = rows
        .iter()
        .map(|r| {
            (
                r.label,
                fmt_commas_f64(r.raw, 0),
                r.adj.map(|a| fmt_commas_f64(a, 0)),
                r.band.map(fmt_commas),
            )
        })
        .collect();

    // Column widths: widest rendered string in each column.
    let raw_w = rendered
        .iter()
        .map(|(_, r, _, _)| r.len())
        .max()
        .unwrap_or(0);
    let adj_w = rendered
        .iter()
        .filter_map(|(_, _, a, _)| a.as_ref().map(String::len))
        .max()
        .unwrap_or(0);
    let band_w = rendered
        .iter()
        .filter_map(|(_, _, _, b)| b.as_ref().map(String::len))
        .max()
        .unwrap_or(0);

    // Fixed layout pieces: 2-space indent, 8-wide label, 4-space gap
    // between columns.
    const INDENT: &str = "  ";
    const LABEL_W: usize = 8;
    const GAP: &str = "    ";

    // Header row: right-align each label over its numeric column.
    let raw_col_end = INDENT.len() + LABEL_W + 1 + raw_w;
    let adj_col_gap = " ns".len() + GAP.len() + adj_w;
    let band_col_gap = " ns".len() + GAP.len() + band_w;
    println!(
        "{:>raw_col_end$}{:>adj_col_gap$}{:>band_col_gap$}",
        "raw", "adjusted", "band",
    );

    // Data rows: label left-aligned, numbers right-aligned in their
    // data-driven widths.
    for (label, raw_s, adj_s, band_s) in &rendered {
        match (adj_s, band_s) {
            (Some(a), Some(b)) => println!(
                "{INDENT}{label:<LABEL_W$} {raw_s:>raw_w$} ns{GAP}{a:>adj_w$} ns{GAP}{b:>band_w$}"
            ),
            (Some(a), None) => {
                println!("{INDENT}{label:<LABEL_W$} {raw_s:>raw_w$} ns{GAP}{a:>adj_w$} ns")
            }
            _ => println!("{INDENT}{label:<LABEL_W$} {raw_s:>raw_w$} ns"),
        }
    }
    println!();
}

struct Row {
    label: &'static str,
    raw: f64,
    adj: Option<f64>,
    band: Option<u64>,
}

impl Row {
    fn with_band(label: &'static str, raw: f64, overhead: f64, band: u64) -> Self {
        Self {
            label,
            raw,
            adj: Some((raw - overhead).max(0.0)),
            band: Some(band),
        }
    }

    fn with_adj(label: &'static str, raw: f64, overhead: f64) -> Self {
        Self {
            label,
            raw,
            adj: Some((raw - overhead).max(0.0)),
            band: None,
        }
    }

    fn raw_only(label: &'static str, raw: f64) -> Self {
        Self {
            label,
            raw,
            adj: None,
            band: None,
        }
    }
}

