    let mean_w = rows.iter().map(|r| r.mean.len()).max().unwrap_or(0);
    let adj_w = rows.iter().map(|r| r.adj_mean.len()).max().unwrap_or(0);

    const INDENT: &str = "  ";
    const GAP: &str = "    ";

