    let hist_mean = hist.mean();
    let hist_adj = (hist_mean - adj).max(0.0);
    println!(
        "{INDENT}{:<label_w$} {:>first_w$}    {GAP}{:>last_w$}    {GAP}{:>count_w$}{GAP}{:>mean_w$} ns{GAP}{:>adj_w$} ns",
        "mean",
        "",
        "",
        fmt_commas(sample_count),
