43	pub fn run_adaptive<B: Bench>(bench: &mut B, cfg: &RunCfg) -> (Histogram<u64>, u64, u64, f64) {
44	    for _ in 0..WARMUP {
45	        black_box(bench.step());
46	    }
47	
48	    let step_cost_ns = estimate_step_cost(bench);
49	    let framing_ns = cfg.overhead.framing_per_sample_ns.max(1.0);
50	    let inner = cfg
