52	        .unwrap_or_else(|| pick_inner(step_cost_ns, framing_ns));
53	    let iterations = cfg
54	        .iterations_override
55	        .unwrap_or_else(|| pick_iterations(step_cost_ns, inner, cfg.target_seconds));
