61	fn estimate_step_cost<B: Bench>(bench: &mut B) -> f64 {
62	    let mut samples: Vec<f64> = (0..ESTIMATE_SAMPLES)
63	        .map(|_| {
64	            let start = minstant::Instant::now();
65	            for _ in 0..ESTIMATE_STEPS {
66	                black_box(bench.step());
67	            }
68	            let total = start.elapsed().as_nanos() as u64;
69	            total as f64 / ESTIMATE_STEPS as f64
70	        })
71	        .collect();
72	    samples.sort_by(|a, b| a.partial_cmp(b).unwrap());
73	    samples[ESTIMATE_SAMPLES / 2]
74	}
