76	fn pick_inner(step_cost_ns: f64, framing_ns: f64) -> u64 {
77	    let target = (FRAMING_DOMINATION_RATIO * framing_ns / step_cost_ns).ceil() as u64;
78	    target.clamp(1, MAX_INNER)
